import{_ as s,D as n,c as i,I as o,j as e,a as t,a4 as r,o as d}from"./chunks/framework.CRCV4hx_.js";const A=JSON.parse('{"title":"Extras","description":"","frontmatter":{},"headers":[],"relativePath":"extras.md","filePath":"extras.md"}'),l={name:"extras.md"},c=e("h1",{id:"extras",tabindex:"-1"},[t("Extras "),e("a",{class:"header-anchor",href:"#extras","aria-label":'Permalink to "Extras"'},"​")],-1),h=e("p",null,"Extras are delicious side dishes that you can add to your Entries, giving your users a little something extra when they make their reservations.",-1),p=e("h2",{id:"managing-extras",tabindex:"-1"},[t("Managing Extras "),e("a",{class:"header-anchor",href:"#managing-extras","aria-label":'Permalink to "Managing Extras"'},"​")],-1),u=e("p",null,[t("You've probably seen this coming, but here it is: Extras are managed in the "),e("strong",null,"Extras"),t(" section of the admin panel.")],-1),m=r('<p>Each Extra has a name, a description, and a price. The price can be calculated in various ways:</p><ul><li><p><strong>Fixed</strong>: A fixed price that gets added to the total price of the reservation.</p></li><li><p><strong>Per day</strong>: You charge the set amount for each day of the reservation.</p></li><li><p><strong>Relative to the reservation price</strong>: You can set a multiplier that gets applied to the total reservation price to determine the price of the Extra. For example, if you set the multiplier to <code>1.5</code> and the total reservation price is <code>100</code>, the Extra will cost <code>150</code>.</p></li><li><p><strong>Relative to a checkout form item</strong>: You can select a field in the <a href="./checkout">checkout form</a> (should be a numerical field) and calculate the price based on the value of that field. For example, if you set the field to <code>adults</code> and the price to <code>10</code>, and the user selects <code>3</code> adults, the Extra will cost <code>30</code>.</p></li></ul><p>The min/max <a href="./dynamic-pricing">dynamic pricing</a> clamp rules also apply to Extras, clamping the per-day total of the Extra after any other adjustments.</p><p>If you enable the <strong>Can add more than one</strong> option, the user can use a quantity field on the frontend to order more than one of that extra, up to the max amount you set with &quot;Maximum number for 1 reservation&quot;.</p><p>You can also override the default name by using the <strong>Override label</strong> field (useful if you have many similar extras and want to differentiate them in the control panel but display the same name to the user).</p><p>After you&#39;ve created your Extras, you need to assign them to the Entries you want them to be available for. To do that, simply open the dropdown menu and select <strong>Mass assign</strong>:</p>',6),f=e("h2",{id:"extra-categories",tabindex:"-1"},[t("Extra Categories "),e("a",{class:"header-anchor",href:"#extra-categories","aria-label":'Permalink to "Extra Categories"'},"​")],-1),x=e("p",null,"If you wish, you can organize your extras in categories. This doesn't alter their functionality in any way, but you can display them to the user organized in a more natural way, plus add a description text on each category. As an added bonus, you can publish/unpublish a whole category.",-1),y=e("p",null,"To use this feature, just add a category and add extras to it (or drag and drop existing extras).",-1),_=e("h2",{id:"extras-field-optional",tabindex:"-1"},[t("Extras Field (Optional) "),e("a",{class:"header-anchor",href:"#extras-field-optional","aria-label":'Permalink to "Extras Field (Optional)"'},"​")],-1),g=e("p",null,[t("Besides the Extras management page, you can also add a "),e("code",null,"Resrv Extras"),t(" field to your Blueprint. While not necessary, it's a good idea to add this field to your Entries so that you can easily see which Extras are available for each Entry.")],-1),b=r('<h2 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h2><p>You can <em>show</em>, <em>hide</em>, or make an Extra <em>required</em> based on a number of different conditions. You can also mix and match conditions.</p><p>For example, here we only show the <code>Late Checkout</code> Extra if the reservation is at least 7 days long:</p>',3),E=r('<p>Required extras display on the frontend as enabled and cannot be disabled by the user, so we suggest you add a note about it in that Extra&#39;s description.</p><h2 id="extras-or-options" tabindex="-1">Extras or Options? <a class="header-anchor" href="#extras-or-options" aria-label="Permalink to &quot;Extras or Options?&quot;">​</a></h2><p>Extras and <a href="./options">Options</a> are very similar, to the point that it can be a bit confusing. Let&#39;s try to clarify this.</p><p>The basic questions you need to ask yourself are:</p><ul><li>Do I want this to apply to all my Entries or just one?</li><li>Does it have a fixed price, or does it depend on the Entry?</li><li>Do I need the advanced pricing options that an <code>Extra</code> offers?</li><li>Do I need to conditionaly require, show or hide an extra based on another extra or variables of the reservation?</li></ul><p>If you answered yes to any of these questions, you&#39;re probably better off using an <code>Extra</code>. In most cases, it&#39;s the best choice.</p><p>For example, if you offer a Transfer service to and from your hotel, the <code>Extra</code> allows you to quickly add it to all the room types and easily manage the price in one place.</p><p>On the other hand, let&#39;s say you rent a boat and want the user to select which cruise to book. If that cruise has a different price for each boat, and each boat has different cruises, you&#39;re better off using an <code>Option</code>.</p><p>In any case, feel free to skip ahead to the <a href="./options">Options</a> docs to learn more about them.</p>',9);function v(T,w,k,I,P,q){const a=n("Image");return d(),i("div",null,[c,h,p,u,o(a,{src:"./img/resrv-extras-list.webp",alt:"The Extras management page."}),m,o(a,{src:"./img/resrv-extras-assign.webp",alt:"The dropdown menu option to assign Extras to Entries."}),f,x,y,_,g,o(a,{src:"./img/resrv-extras-field.webp",alt:"The guests of this room type can't order a late checkout."}),b,o(a,{src:"./img/resrv-extras-conditions.webp",alt:"Extra conditions."}),E])}const S=s(l,[["render",v]]);export{A as __pageData,S as default};
